'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var getPrototypeOf = require( '@stdlib/utils/get-prototype-of' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var hasOwn = require( '@stdlib/assert/has-own-property' );
var descriptor = require( '@stdlib/utils/property-descriptor' );


// VARIABLES //

var typedArrayPrototype = getPrototypeOf( Float64Array.prototype );
var getLength = descriptor( typedArrayPrototype, 'length' ).get;
var getBuffer = descriptor( typedArrayPrototype, 'buffer' ).get;
var getByteOffset = descriptor( typedArrayPrototype, 'byteOffset' ).get;
var getByteLength = descriptor( typedArrayPrototype, 'byteLength' ).get;


// FUNCTIONS //

/**
* Checks safe physical matrix bounds without invoking untrusted metadata.
*
* @private
* @param {Float64Array} data - typed view
* @param {integer} N - square order
* @param {integer} s1 - row stride
* @param {integer} s2 - column stride
* @param {integer} offset - starting index
* @returns {boolean} whether the view is compatible
*/
function isView( data, N, s1, s2, offset ) {
	var length;
	var proto;
	var lo;
	var hi;
	var a;
	var b;

	if ( !isFloat64Array( data ) ) {
		return false;
	}
	proto = getPrototypeOf( data );
	if ( proto !== Float64Array.prototype ) {
		return false;
	}
	if ( hasOwn( data, 'length' ) || hasOwn( data, 'buffer' ) || hasOwn( data, 'byteOffset' ) || hasOwn( data, 'byteLength' ) || hasOwn( proto, 'length' ) || hasOwn( proto, 'buffer' ) || hasOwn( proto, 'byteOffset' ) || hasOwn( proto, 'byteLength' ) ) {
		return false;
	}
	a = (N-1)*s1;
	b = (N-1)*s2;
	lo = offset + ( (a < 0) ? a : 0 ) + ( (b < 0) ? b : 0 );
	hi = offset + ( (a > 0) ? a : 0 ) + ( (b > 0) ? b : 0 );
	length = getLength.call( data );
	if ( s1 < -2147483647 || s1 > 2147483647 || s2 < -2147483647 || s2 > 2147483647 || offset > 2147483647 || a < -2147483647 || a > 2147483647 || b < -2147483647 || b > 2147483647 || hi > 2147483647 ) {
		return false;
	}
	return isSafeInteger( a ) && isSafeInteger( b ) && isSafeInteger( lo ) && isSafeInteger( hi ) && lo >= 0 && hi < length;
}


// MAIN //

/**
* Checks whether normalized arguments can use the native interface.
*
* @private
* @param {ArrayLike} args - normalized ndarray arguments
* @returns {boolean} whether arguments are safely marshalable
*/
function canUseNative( args ) {
	var buffer;
	var offset;
	var length;
	var data;
	var N;
	var i;

	N = args[ 1 ];
	if ( N <= 0 || N > 1073741823 ) {
		return false;
	}
	if ( !isView( args[2], N, args[3], args[4], args[5] ) || !isView( args[6], N, args[7], args[8], args[9] ) || !isView( args[10], 2*N, args[11], 0, args[12] ) ) {
		return false;
	}
	buffer = getBuffer.call( args[10] );
	offset = getByteOffset.call( args[10] );
	length = getByteLength.call( args[10] );
	for ( i = 2; i <= 6; i += 4 ) {
		data = args[ i ];
		if ( getBuffer.call( data ) === buffer && getByteOffset.call( data ) < offset+length && offset < getByteOffset.call( data )+getByteLength.call( data ) ) {
			return false;
		}
	}
	return true;
}


// EXPORTS //

module.exports = canUseNative;
